def isValidMarkup(s):
    n = len(s)
    if s[0] != '<':
        return False
    stack = []
    i = 0
    while i < n:
        if s[i] == '<':
            j = s.find('>', i + 1)
            if j == -1:
                return False
            closing = i + 1 < n and s[i + 1] == '/'
            name = s[i + 2:j] if closing else s[i + 1:j]
            if not 1 <= len(name) <= 9:
                return False
            for c in name:
                if c < 'A' or c > 'Z':
                    return False
            if closing:
                if not stack or stack.pop() != name:
                    return False
                if not stack:
                    return j == n - 1
            else:
                stack.append(name)
            i = j + 1
        else:
            if not stack:
                return False
            i += 1
    return False
